var campaigns=[],statuses={"Email Sent":{color:"#1abc9c",label:"text-bg-success",icon:"fa-envelope"},"Emails Sent":{color:"#1abc9c",label:"text-bg-success",icon:"fa-envelope"},"In progress":{label:"text-bg-primary"},Queued:{label:"text-bg-info"},Completed:{label:"text-bg-success"},"Email Opened":{color:"#f9bf3b",label:"text-bg-warning",icon:"fa-envelope"},"Email Reported":{color:"#45d6ef",label:"text-bg-info",icon:"fa-bullhorn"},"Clicked Link":{color:"#F39C12",label:"text-bg-clicked",icon:"fa-mouse-pointer"},Success:{color:"#f05b4f",label:"text-bg-danger",icon:"fa-exclamation"},Error:{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-times"},"Error Sending Email":{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-times"},"Submitted Data":{color:"#f05b4f",label:"text-bg-danger",icon:"fa-exclamation"},Unknown:{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-question"},Sending:{color:"#428bca",label:"text-bg-primary",icon:"fa-spinner"},"Campaign Created":{label:"text-bg-success",icon:"fa-rocket"}},statsMapping={sent:"Email Sent",opened:"Email Opened",email_reported:"Email Reported",clicked:"Clicked Link",submitted_data:"Submitted Data"};function deleteCampaign(e){confirm("Delete "+campaigns[e].name+"?")&&api.campaignId.delete(campaigns[e].id).done(function(e){successFlash(e.message),location.reload()})}function renderPieChart(e){return GophishCharts.renderDoughnut({elemId:e.elemId,title:e.title,data:e.data,colors:e.colors,centerFontSize:16})}function generateStatsPieCharts(e){var a=[],t={},s=0;e.forEach(function(e){Object.entries(e.stats).forEach(function(e){var a=e[0],n=e[1];"total"!=a?t[a]?t[a]+=n:t[a]=n:s+=n})}),Object.entries(t).forEach(function(e){var t=e[0],n=e[1];if(t in statsMapping){status_label=statsMapping[t],a.push({name:status_label,y:Math.floor(n/s*100),count:n}),a.push({name:"",y:100-Math.floor(n/s*100)});renderPieChart({elemId:t+"_chart",title:status_label,name:t,data:a,colors:[statuses[status_label].color,"#dddddd"]});a=[]}})}function generateTimelineChart(e){var a=[];e.forEach(function(e){var t=moment.utc(e.created_date).local();e.y=0,e.y+=e.stats.clicked,e.y=Math.floor(e.y/e.stats.total*100),a.push({campaign_id:e.id,name:e.name,x:t.valueOf(),y:e.y})}),GophishCharts.renderOverview({elemId:"overview_chart",title:"Phishing Success Overview",data:a})}document.addEventListener("DOMContentLoaded",function(){api.campaigns.summary().done(function(e){document.getElementById("loading").style.display="none",(campaigns=e.campaigns).length>0?(document.getElementById("dashboard").style.display="",campaignTable=new DataTable("#campaignTable",{columnDefs:[{orderable:!1,targets:"no-sort"},{className:"color-sent",targets:[2]},{className:"color-opened",targets:[3]},{className:"color-clicked",targets:[4]},{className:"color-success",targets:[5]},{className:"color-reported",targets:[6]}],order:[[1,"desc"]]}),campaignRows=[],campaigns.forEach(function(e,a){var t=moment(e.created_date).format("MMMM Do YYYY, h:mm:ss a"),s=statuses[e.status].label||"text-bg-secondary";if(moment(e.launch_date).isAfter(moment()))var n="Scheduled to start: "+moment(e.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>Number of recipients: "+e.stats.total;else n="Launch Date: "+moment(e.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>Number of recipients: "+e.stats.total+"<br><br>Emails opened: "+e.stats.opened+"<br><br>Emails clicked: "+e.stats.clicked+"<br><br>Submitted Credentials: "+e.stats.submitted_data+"<br><br>Errors : "+e.stats.error+"<br><br>Reported : "+e.stats.email_reported;campaignRows.push([escapeHtml(e.name),t,e.stats.sent,e.stats.opened,e.stats.clicked,e.stats.submitted_data,e.stats.email_reported,'<span class="badge '+s+'" data-bs-toggle="tooltip" data-bs-placement="right" data-bs-html="true" title="'+n+'">'+e.status+"</span>","<div class='float-end'><a class='btn btn-primary' href='/campaigns/"+e.id+"' data-bs-toggle='tooltip' data-bs-placement='left' title='View Results'>                    <i class='fa fa-bar-chart'></i>                    </a>                    <button class='btn btn-danger' onclick='deleteCampaign("+a+")' data-bs-toggle='tooltip' data-bs-placement='left' title='Delete Campaign'>                    <i class='fa fa-trash-o'></i>                    </button></div>"]),bsInitTooltips()}),campaignTable.rows.add(campaignRows).draw(),generateStatsPieCharts(campaigns),generateTimelineChart(campaigns)):document.getElementById("emptyMessage").style.display=""}).fail(function(){errorFlash("Error fetching campaigns")})});